const item = $input.first().json.body || $input.first().json;

const licensePlate = item.licensePlate || item.vehicleNumber || 'KA01MJ4521';
const rfidTag = item.rfidTag || item.rfidTagNumber || 'N/A';
const direction = item.direction || 'IN'; // IN, OUT
const triggerSource = item.triggerSource || 'ANPR'; // ANPR, RFID, MANUAL, PATROL
const isResidentVehicle = item.isResidentVehicle ?? false;
const registeredResident = item.registeredResident || 'Unknown';
const assignedSlot = item.assignedSlot || 'NONE';
const detectedSlot = item.detectedSlot || item.parkingSlotNumber || 'UNKNOWN';
const violationType = item.violationType || (detectedSlot !== 'UNKNOWN' && assignedSlot !== 'NONE' && detectedSlot !== assignedSlot ? 'UNAUTHORIZED_SLOT' : 'NONE');
// UNAUTHORIZED_SLOT, DOUBLE_PARKING, FIRE_LANE_BLOCK, EV_BAY_MISUSE, VISITOR_OVERSTAY, SPEEDING
const pastViolationsCount = item.pastViolationsCount ?? 0;
const gateName = item.gateName || 'North Gate ANPR Boom Barrier';

const prompt = `You are the Automated Parking Marshal and ANPR Barrier Controller for Mana Community Society.
Evaluate this real-time vehicle entry or parking violation telemetry against society traffic and parking bylaws.

Vehicle & Event Telemetry:
- License Plate: ${licensePlate}
- RFID Tag: ${rfidTag}
- Event Direction: ${direction} via ${gateName}
- Trigger Source: ${triggerSource}
- Resident Affiliation: ${isResidentVehicle ? `Yes (${registeredResident}, Assigned: ${assignedSlot})` : 'Unregistered / Visitor Vehicle'}
- Detected Parking Location: ${detectedSlot}
- Reported Violation: ${violationType}
- Prior Parking Offenses: ${pastViolationsCount}

Automated Enforcement Mandates:
1. Determine Barrier Action (OPEN_BARRIER, KEEP_LOCKED_FLAG_GUARD, MANUAL_PASS_REQUIRED).
2. Adjudicate Parking Violation Severity (CRITICAL_SAFETY_HAZARD for fire lanes, REPEAT_ENCROACHMENT, MINOR_FIRST_TIME, NO_VIOLATION).
3. Progressive Penalty Escalation: If violation present, assign exact action ('OFFICIAL_WARNING', 'FINE_500_INR', 'FINE_1000_INR_WHEEL_CLAMP', 'VEHICLE_TOWING_ESCALATION').
4. Draft immediate SMS/WhatsApp notification for the vehicle owner / resident.
5. Security Patrol instruction (e.g. place violation sticker, apply physical clamp, clear fire access route).

Respond ONLY with a valid JSON object matching this schema:
{
  "barrierDecision": "OPEN_BARRIER" | "KEEP_LOCKED_FLAG_GUARD" | "MANUAL_PASS_REQUIRED",
  "isViolation": boolean,
  "violationClassification": "NO_VIOLATION" | "MINOR_FIRST_TIME" | "REPEAT_ENCROACHMENT" | "CRITICAL_SAFETY_HAZARD",
  "penaltyEnforcement": "NONE" | "OFFICIAL_WARNING" | "FINE_500_INR" | "FINE_1000_INR_WHEEL_CLAMP" | "VEHICLE_TOWING_ESCALATION",
  "fineAmount": number,
  "patrolInstructions": "Direct task for parking warden / security patrol",
  "ownerNotificationMessage": "Text message for resident or driver explaining the issue",
  "systemLogNotes": "Audit entry note for Society Command Center"
}`;

return [{
  json: {
    licensePlate,
    violationType,
    direction,
    prompt
  }
}];

const geminiResponse = $input.first().json;
const meta = $('Prepare ANPR Enforcement Prompt').first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  const hasViol = (meta.violationType && meta.violationType !== 'NONE');
  parsed = {
    barrierDecision: hasViol ? "KEEP_LOCKED_FLAG_GUARD" : "OPEN_BARRIER",
    isViolation: hasViol,
    violationClassification: hasViol ? "REPEAT_ENCROACHMENT" : "NO_VIOLATION",
    penaltyEnforcement: hasViol ? "FINE_500_INR" : "NONE",
    fineAmount: hasViol ? 500 : 0,
    patrolInstructions: hasViol ? "Verify unauthorized parking slot and place official notice citation." : "Allow entry without delay.",
    ownerNotificationMessage: hasViol ? `Vehicle ${meta.licensePlate} parked in unauthorized bay. Please relocate immediately to avoid wheel clamping.` : `Vehicle ${meta.licensePlate} authorized.`,
    systemLogNotes: "Automated fallback rule evaluated."
  };
}

return [{
  json: {
    status: "success",
    evaluatedAt: new Date().toISOString(),
    vehicle: meta.licensePlate,
    enforcementResult: parsed
  }
}];
